export default function prepare({ event }) {
  const x = JSON.parse(event);
  if (!["classify", "approve", "reject"].includes(x.kind)) throw Error("Invalid request type");
  if (x.kind === "classify") {
    if (typeof x.enquiry !== "string" || !x.enquiry.trim()) throw Error("Missing enquiry");
    return {
      kind: x.kind,
      enquiry: x.enquiry,
      event: {
        start: { dateTime: "2000-01-01T00:00:00Z" },
        end: { dateTime: "2000-01-01T00:30:00Z" },
      },
      to: "",
      subject: "",
      message: "",
    };
  }
  if (
    typeof x.name !== "string" ||
    typeof x.email !== "string" ||
    typeof x.enquiry !== "string" ||
    typeof x.summary !== "string" ||
    typeof x.requestId !== "string" ||
    !x.requestId ||
    !Number.isFinite(Date.parse(x.dateTime))
  )
    throw Error("Invalid appointment decision");
  const start = new Date(x.dateTime);
  const result = {
    summary: `Appointment Scheduled - ${x.name}`,
    description: `${x.summary}\n\nOriginal message:\n> ${x.enquiry}`,
    start: { dateTime: start.toISOString() },
    end: { dateTime: new Date(+start + 1800000).toISOString() },
    attendees: [{ email: x.email }],
    conferenceData: {
      createRequest: { requestId: x.requestId, conferenceSolutionKey: { type: "hangoutsMeet" } },
    },
  };
  return {
    kind: x.kind,
    enquiry: x.enquiry,
    event: result,
    to: x.email,
    subject: `Appointment Request Rejected for ${x.dateTime}`,
    message: `Dear ${x.name},\n\nUnfortunately, we cannot schedule the requested appointment at the requested time.\n\nKind regards`,
  };
}

