export default function select({ classification, created, rejected }) {
  if (classification != null) return { response: classification };
  if (created != null) return { response: { ok: true, decision: "approved" } };
  if (rejected != null) return { response: { ok: true, decision: "rejected" } };
  throw Error("Missing result");
}
